def bell_number(n):
    if n == 0:
        return 1
    bell = [0] * (n + 1)
    bell[0] = 1
    for i in range(1, n + 1):
        bell[i] = 0
        for j in range(0, i):
            bell[i] += bell[j] * (i - 1) ** (i - j - 1)
    return bell[n]

