def search(arr):
    if not arr:
        return None

    if len(arr) == 1:
        return arr[0]

    # Check if the first element is the unique one
    if arr[0] != arr[1]:
        return arr[0]

    # Check if the last element is the unique one
    if arr[-1] != arr[-2]:
        return arr[-1]

    # Binary search for the unique element
    left, right = 0, len(arr) - 1

    while left <= right:
        mid = (left + right) // 2

        # Check if the middle element is the unique one
        if (mid == 0 or arr[mid] != arr[mid-1]) and (mid == len(arr)-1 or arr[mid] != arr[mid+1]):
            return arr[mid]

        # If the middle element is the same as its left neighbor
        if mid > 0 and arr[mid] == arr[mid-1]:
            # If the number of elements to the left of mid is odd, the unique element is on the left side
            if (mid - left + 1) % 2 == 1:
                right = mid - 2
            else:
                left = mid + 1
        # If the middle element is the same as its right neighbor
        elif mid < len(arr)-1 and arr[mid] == arr[mid+1]:
            # If the number of elements to the left of mid is even, the unique element is on the left side
            if (mid - left) % 2 == 0:
                right = mid - 1
            else:
                left = mid + 2

    return None

def amicable_numbers_sum(n):
    def sum_of_proper_divisors(num):
        if num == 1:
            return 0
        total = 1  # 1 is a proper divisor of all numbers > 1
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                total += i
                if i != num // i:
                    total += num // i
        return total

    amicable_sum = 0
    for i in range(1, n + 1):
        sum_div = sum_of_proper_divisors(i)
        if sum_div != i and sum_div <= n and sum_of_proper_divisors(sum_div) == i:
            amicable_sum += i

    return amicable_sum

def sum_common_divisors(a, b):
    # Find the minimum of a and b
    min_num = min(a, b)

    # Initialize the sum
    total = 0

    # Iterate from 1 to min_num to find common divisors
    for i in range(1, min_num + 1):
        if a % i == 0 and b % i == 0:
            total += i

    return total

def find_solution(a, b, n):
    # Extended Euclidean algorithm
    def extended_gcd(a, b):
        if b == 0:
            return (a, 1, 0)
        else:
            gcd, x, y = extended_gcd(b, a % b)
            return (gcd, y, x - (a // b) * y)

    gcd, x, y = extended_gcd(a, b)

    # Check if a solution exists
    if n % gcd != 0:
        return None

    # Scale the solution
    factor = n // gcd
    x_scaled = x * factor
    y_scaled = y * factor

    return (x_scaled, y_scaled)

