def set_left_most_unset_bit(n):
    if n == 0:
        return 1  # Set the first bit

    # Find the position of the most significant bit
    msb_pos = n.bit_length() - 1

    # Check if there's an unset bit to the left of the MSB
    # We need to check bits from msb_pos-1 down to 0
    for i in range(msb_pos - 1, -1, -1):
        if not (n & (1 << i)):
            # Found the left most unset bit, set it
            return n | (1 << i)

    # If we get here, all bits from msb_pos down to 0 are set
    # So we need to add a new bit at the left
    return n | (1 << (msb_pos + 1))

