        return None

    # Initialize the two largest and two smallest numbers
    max1 = max2 = float('-inf')
    min1 = min2 = float('inf')

    for num in arr:
        # Update the two largest numbers
        if num > max1:
            max2 = max1
            max1 = num
        elif num > max2:
            max2 = num

        # Update the two smallest numbers
        if num < min1:
            min2 = min1
            min1 = num
        elif num < min2:
            min2 = num

    # Calculate products
    product_max = max1 * max2
    product_min = min1 * min2

    # Return the pair with the higher product
