def get_median(arr1, arr2, n):
    # Base cases
    if n == 1:
        return (arr1[0] + arr2[0]) / 2

    if n == 2:
        return (max(arr1[0], arr2[0]) + min(arr1[1], arr2[1])) / 2

    # Find the median of each array
    m1 = median(arr1, n)
    m2 = median(arr2, n)

    # If the medians are equal, return either one
    if m1 == m2:
        return m1

    # If m1 < m2, the median must be in the right half of arr1 or the left half of arr2
    if m1 < m2:
        if n % 2 == 0:
            return get_median(arr1[n//2:], arr2[:n//2], n//2)
        else:
            return get_median(arr1[n//2:], arr2[:n//2+1], n//2+1)
    # If m1 > m2, the median must be in the left half of arr1 or the right half of arr2
    else:
        if n % 2 == 0:
            return get_median(arr1[:n//2], arr2[n//2:], n//2)
        else:
            return get_median(arr1[:n//2+1], arr2[n//2:], n//2+1)

