def check_expression(expression):
    stack = []
    opening_brackets = {'{': '}', '[': ']', '(': ')'}
    closing_brackets = {'}': '{', ']': '[', ')': '('}

    for char in expression:
        if char in opening_brackets:
            stack.append(char)
        elif char in closing_brackets:
            if not stack or stack[-1] != closing_brackets[char]:
                return False
            stack.pop()

    return len(stack) == 0

