def find_length(s):
    # Convert to array where 0s are +1 and 1s are -1
    arr = [1 if c == '0' else -1 for c in s]

    # Calculate prefix sums
    prefix = [0]
    for num in arr:
        prefix.append(prefix[-1] + num)

    # For each prefix sum value, store the earliest index
    earliest = {}
    for i, val in enumerate(prefix):
        if val not in earliest:
            earliest[val] = i

    max_length = 0
    # For each position, find the earliest position with a smaller prefix sum
    for i in range(len(prefix)):
        for val in range(prefix[i] - 1, min(earliest.keys()) - 1, -1):
            if val in earliest:
                max_length = max(max_length, i - earliest[val])
                break

    return max_length

