def get_total_number_of_sequences(m, n):
    # Initialize dp table
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Base case: sequences of length 1
    for j in range(1, m + 1):
        dp[1][j] = 1

    # Fill the dp table
    for i in range(2, n + 1):
        for j in range(1, m + 1):
            # Sum of dp[i-1][k] for k from 1 to floor(j/2)
            for k in range(1, j // 2 + 1):
                dp[i][j] += dp[i-1][k]

    # Sum up all sequences of length n
    return sum(dp[n][j] for j in range(1, m + 1))

import math

def get_total_number_of_sequences(n, m):
    if n == 0:
        return 0

    # dp[i][j] = number of valid sequences of length i where the i-th element is j
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Initialize for sequences of length 1
    for j in range(1, m + 1):
        dp[1][j] = 1

    # Fill the DP table
    for i in range(2, n + 1):
        for j in range(1, m + 1):
            # The previous element must be at least ceil(j/2)
            min_prev = math.ceil(j / 2)
            for k in range(min_prev, m + 1):
                dp[i][j] += dp[i-1][k]

    # Sum up all valid sequences of length n
    return sum(dp[n][j] for j in range(1, m + 1))

