def max_sum_increasing_subseq(arr, n, i, k):
    # Get the kth element
    kth_element = arr[k]

    # Filter elements from the prefix that are less than the kth element
    valid_elements = [arr[j] for j in range(i + 1) if arr[j] < kth_element]

    # If no valid elements, just return the kth element
    if not valid_elements:
        return kth_element

    # Find the maximum sum of an increasing subsequence in valid_elements
    dp = valid_elements.copy()

    for j in range(len(valid_elements)):
        for l in range(j):
            if valid_elements[l] < valid_elements[j]:
                dp[j] = max(dp[j], dp[l] + valid_elements[j])

    # The maximum sum is the max value in dp plus the kth element
    return max(dp) + kth_element

