def sequence(n):
    if n <= 0:
        return 0

    # Initialize the sequence with the first two values
    p = [0, 1, 1]  # Using 1-based indexing

    if n <= 2:
        return p[n]

    # Calculate the sequence up to n
    for i in range(3, n + 1):
        next_val = p[p[i-1]] + p[i-p[i-1]]
        p.append(next_val)

    return p[n]

def sequence(n):
    if n <= 0:
        return 0
    if n <= 2:
        return 1

    # Initialize an array to store the sequence values
    dp = [0] * (n + 1)
    dp[1] = dp[2] = 1

    for i in range(3, n + 1):
        dp[i] = dp[dp[i-1]] + dp[i - dp[i-1]]

    return dp[n]

