def next_smallest_palindrome(n):
    s = str(n)
    length = len(s)

    # Special case for single digit
    if length == 1:
        return n + 1 if n < 9 else 11

    # Split the number into left and right halves
    half = length // 2
    left = s[:half]
    middle = s[half] if length % 2 == 1 else ""
    right = s[half + (1 if length % 2 == 1 else 0):]

    # Create a palindrome by mirroring the left half
    if length % 2 == 1:
        palindrome = left + middle + left[::-1]
    else:
        palindrome = left + left[::-1]

    # If the palindrome is greater than the original number, return it
    if int(palindrome) > n:
        return int(palindrome)

    # Otherwise, increment the left half (and middle if odd length)
    if length % 2 == 1:
        # Increment the middle digit
        if middle != "9":
            new_middle = str(int(middle) + 1)
            return int(left + new_middle + left[::-1])
        else:
            # Middle is 9, so we need to carry over
            new_middle = "0"
            new_left = str(int(left + "9") + 1)[:-1]  # Add 9 to handle carry, then increment, then remove the added 9
            return int(new_left + new_middle + new_left[::-1])
    else:
        # Increment the left half
        new_left = str(int(left) + 1)
        # Handle the case where incrementing increases the length (e.g., 99 -> 100)
        if len(new_left) > len(left):
            return int("1" + "0" * (length - 1) + "1")
        return int(new_left + new_left[::-1])

def next_smallest_palindrome(n):
    s = str(n + 1)  # Start with n+1 since we want a palindrome greater than n
    length = len(s)

    # For single digit numbers
    if length == 1:
        return int(s) if s != '9' else 11

    # Find the middle index
    mid = length // 2

    # Create a palindrome by mirroring the left half
    if length % 2 == 0:
        palindrome = s[:mid] + s[:mid][::-1]
    else:
        palindrome = s[:mid+1] + s[:mid][::-1]

    # If the palindrome is greater than n+1, we're done
    if int(palindrome) > n:
        return int(palindrome)

    # Otherwise, we need to increment the middle and propagate carry
    if length % 2 == 0:
        left = s[:mid]
        right = s[mid:]

        # Increment the left half
        left_int = int(left) + 1
        left_str = str(left_int)

        # If the length of left_str is greater than left, it means we had a carry
        if len(left_str) > len(left):
            # For example, 99 -> 100, so the palindrome is 101
            return int('1' + '0' * (length - 1) + '1')

        # Create the new palindrome
        palindrome = left_str + left_str[::-1]
    else:
        left = s[:mid]
        middle = s[mid]
        right = s[mid+1:]

        # Increment the middle
        if middle != '9':
            middle = str(int(middle) + 1)
            palindrome = left + middle + left[::-1]
        else:
            # Middle is 9, so we need to increment the left part
            left_int = int(left + middle) + 1
            left_str = str(left_int)

            # If the length of left_str is greater than left+middle, it means we had a carry
            if len(left_str) > len(left + middle):
                # For example, 999 -> 1001
                return int('1' + '0' * (length - 1) + '1')

            # Create the new palindrome
            palindrome = left_str + left_str[:-1][::-1]

    return int(palindrome)

