def remove_dirty_chars(str1, str2):
    # Create a set of characters to remove for O(1) lookup
    chars_to_remove = set(str2)

    # Build the result string by keeping only characters not in chars_to_remove
    result = []
    for char in str1:
        if char not in chars_to_remove:
            result.append(char)

    return ''.join(result)

