def find_tuples(list_of_tuples, k):
    result = []
    for tuple_item in list_of_tuples:
        all_divisible = True
        for element in tuple_item:
            if element % k != 0:
                all_divisible = False
                break
        if all_divisible:
            result.append(tuple_item)
    return result

