def is_undulating(n):
    s = str(n)
    if len(s) < 2:
        return False

    # Get the first two digits
    first, second = s[0], s[1]

    # If the first two digits are the same, it's not undulating
    if first == second:
        return False

    # Check if the pattern continues
    for i in range(len(s)):
        if i % 2 == 0:
            if s[i] != first:
                return False
        else:
            if s[i] != second:
                return False

    return True

