    # And the digit at position 0 should be different from the digit at position 1

    # Check if all even positions have the same digit
    even_digit = s[0]
    for i in range(0, len(s), 2):
        if s[i] != even_digit:
            return False

    # Check if all odd positions have the same digit
    odd_digit = s[1]
    for i in range(1, len(s), 2):
        if s[i] != odd_digit:
            return False

    # Check if the two digits are different
    if even_digit == odd_digit:
        return False

    return True

def is_undulating(n):
    s = str(n)
    # Check if there are exactly two distinct digits
    if len(set(s)) != 2:
        return False
    # Check if digits alternate
    for i in range(len(s) - 1):
        if s[i] == s[i+1]:
            return False
    return True

def Find_Min_Length(list_of_lists):
    if not list_of_lists:
        return 0

    min_length = len(list_of_lists[0])
    for lst in list_of_lists[1:]:
        current_length = len(lst)
        if current_length < min_length:
            min_length = current_length

    return min_length

