def magic_square_test(matrix):
    # Check if it's a square matrix
    n = len(matrix)
    if n == 0:
        return False

    for row in matrix:
        if len(row) != n:
            return False

    # Calculate the target sum (sum of first row)
    target_sum = sum(matrix[0])

    # Check all rows
    for row in matrix:
        if sum(row) != target_sum:
            return False

    # Check all columns
    for col in range(n):
        col_sum = sum(matrix[row][col] for row in range(n))
        if col_sum != target_sum:
            return False

    # Check main diagonal
    diag_sum = sum(matrix[i][i] for i in range(n))
    if diag_sum != target_sum:
        return False

    # Check anti-diagonal
    anti_diag_sum = sum(matrix[i][n-1-i] for i in range(n))
    if anti_diag_sum != target_sum:
        return False

    return True

