def pancake_sort(arr):
    # Make a copy of the input array to avoid modifying the original
    result = arr.copy()
    n = len(result)

    # Start from the full length and reduce by 1 each time
    for curr_size in range(n, 1, -1):
        # Find the index of the maximum element in the unsorted portion
        max_idx = 0
        for i in range(1, curr_size):
            if result[i] > result[max_idx]:
                max_idx = i

        # If the maximum element is not at the end of the unsorted portion
        if max_idx != curr_size - 1:
            # If the maximum element is not at the front, flip to bring it to the front
            if max_idx != 0:
                # Flip the array up to the position of the maximum element
                result[:max_idx+1] = result[:max_idx+1][::-1]

            # Flip the entire unsorted portion to move the maximum element to its correct position
            result[:curr_size] = result[:curr_size][::-1]

    return result

def pancake_sort(arr):
