    result = arr.copy()

    # Start from the full array and reduce the size by 1 each time
    for curr_size in range(len(result), 1, -1):
        # Find the index of the maximum element in the unsorted part
        max_idx = 0
        for i in range(1, curr_size):
            if result[i] > result[max_idx]:
                max_idx = i

        # If the maximum is already at its correct position, skip
        if max_idx == curr_size - 1:
            continue

        # If the maximum is not at the beginning, flip it to the beginning
        if max_idx != 0:
            # Flip from 0 to max_idx
            result[:max_idx+1] = result[:max_idx+1][::-1]

        # Now flip from 0 to curr_size-1 to move the maximum to its correct position
        result[:curr_size] = result[:curr_size][::-1]

    return result

