def next_power_of_2(n):
    if n <= 0:
        return 1
    # Check if n is already a power of 2
    if (n & (n - 1)) == 0:
        return n
    # Find the position of the most significant bit
    power = 1
    while power < n:
        power <<= 1
    return power

