    n = len(arr)

    # MSIS[i] = maximum sum increasing subsequence ending at i
    msis = [0] * n
    for i in range(n):
        msis[i] = arr[i]
        for j in range(i):
            if arr[j] < arr[i] and msis[j] + arr[i] > msis[i]:
                msis[i] = msis[j] + arr[i]

    # MSDS[i] = maximum sum decreasing subsequence starting at i
    msds = [0] * n
    for i in range(n-1, -1, -1):
        msds[i] = arr[i]
        for j in range(i+1, n):
            if arr[j] < arr[i] and msds[j] + arr[i] > msds[i]:
                msds[i] = msds[j] + arr[i]

