def max_sub_array_sum_repeated(arr, n, k):
    # Find the maximum subarray sum within a single copy using Kadane's algorithm
    max_single = float('-inf')
    current_sum = 0
    for num in arr:
        current_sum = max(num, current_sum + num)
        max_single = max(max_single, current_sum)

    # Find the maximum prefix sum
    max_prefix = float('-inf')
    current_sum = 0
    for num in arr:
        current_sum += num
        max_prefix = max(max_prefix, current_sum)

    # Find the maximum suffix sum
    max_suffix = float('-inf')
    current_sum = 0
    for num in reversed(arr):
        current_sum += num
        max_suffix = max(max_suffix, current_sum)

    # Find the total sum of the array
    total_sum = sum(arr)

    # If k == 1, the answer is just the maximum subarray sum within a single copy
    if k == 1:
        return max_single

    # If the total sum is positive, we can include as many full copies as possible
    if total_sum > 0:
        return max(max_single, max_suffix + (k-2) * total_sum + max_prefix)
    else:
        # If the total sum is not positive, we can only include at most two copies
        return max(max_single, max_suffix + max_prefix)

def max_sub_array_sum_repeated(arr, n, k):
    # Case 1: Maximum subarray within a single copy
    max_single = kadane(arr)

    if k == 1:
        return max_single

    # Calculate prefix and suffix sums
    prefix_sums = [0] * n
    prefix_sums[0] = arr[0]
    for i in range(1, n):
        prefix_sums[i] = prefix_sums[i-1] + arr[i]

    suffix_sums = [0] * n
    suffix_sums[n-1] = arr[n-1]
    for i in range(n-2, -1, -1):
        suffix_sums[i] = suffix_sums[i+1] + arr[i]

    max_prefix = max(prefix_sums)
    max_suffix = max(suffix_sums)

    total_sum = sum(arr)

    # Case 2: Subarray spanning multiple copies
    if total_sum > 0:
