def catalan_number(n):
    if n == 0:
        return 1

    # Calculate the binomial coefficient (2n choose n)
    # We'll use an iterative approach to avoid large intermediate values
    result = 1
    for i in range(1, n+1):
        result = result * (n + i) // i

    # Divide by (n+1) to get the Catalan number
    return result // (n + 1)

