def sum_Of_product(n):
    def binomial_coefficient(n, k):
        # Calculate C(n, k) = n! / (k! * (n-k)!)
        if k > n - k:
            k = n - k
        result = 1
        for i in range(k):
            result = result * (n - i) // (i + 1)
        return result

    total = 0
    for k in range(n):
        total += binomial_coefficient(n, k) * binomial_coefficient(n, k + 1)

    return total

