def get_pairs_count(nums, target):
    # Create a frequency dictionary
    freq = {}
    for num in nums:
        freq[num] = freq.get(num, 0) + 1

    count = 0
    # Iterate through unique numbers
    for num in freq:
        complement = target - num
        # If complement exists in the frequency dictionary
        if complement in freq:
            # If num and complement are the same, count combinations
            if num == complement:
                count += freq[num] * (freq[num] - 1) // 2
            # If num is less than complement, count pairs
            elif num < complement:
                count += freq[num] * freq[complement]

    return count

