def left_rotate(n, d):
    # Ensure we're working with 32 bits
    n = n & 0xFFFFFFFF
    # Rotate left by d bits
    return ((n << d) & 0xFFFFFFFF) | (n >> (32 - d))

def left_rotate(x, n):
    # Ensure we're working with 32 bits
    x = x & 0xFFFFFFFF
    # Perform the left rotation
    return ((x << n) & 0xFFFFFFFF) | (x >> (32 - n))

